-- calc_transactions_amount
-- Field: Transactions.Amount
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_transactions_amount(p_transaction_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT quantity FROM transactions WHERE transaction_id = p_transaction_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_transactions_product_unit_price(p_transaction_id)) AS v OFFSET 0) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

